import numpy as np

def fee_apply(r):
    if r["amount"] > 1500:
        return 0
    if r["items"] >= 4:
        return 60
    return 15 * r["items"]
def fee_col(d):
    return np.where(d["amount"]>1500,0,np.where(d["items"]>=4,60,15*d["items"]))
